'use client';

import { OpenfortProvider, AuthProvider } from '@openfort/react';
import { getDefaultConfig, OpenfortWagmiBridge } from '@openfort/react/wagmi';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { baseSepolia, base } from 'viem/chains';
import { createConfig, WagmiProvider } from 'wagmi';
import type { ReactNode } from 'react';
import { AuthSessionProvider } from '@/components/auth/auth-session-provider';

const publishableKey = process.env.NEXT_PUBLIC_OPENFORT_PUBLIC_KEY;
const shieldPublishableKey = process.env.NEXT_PUBLIC_SHIELD_API_KEY;

const walletConnectProjectId =
  process.env.NEXT_PUBLIC_WALLET_CONNECT_PROJECT_ID || undefined;

const wagmiConfig = createConfig(
  getDefaultConfig({
    appName: 'InfraFund',
    chains: [baseSepolia, base],
    ...(walletConnectProjectId ? { walletConnectProjectId } : {}),
  })
);

const queryClient = new QueryClient();

function OpenfortNotConfigured() {
  return (
    <div className="rounded-lg border border-yellow-500 bg-yellow-900/20 p-4 text-left text-sm text-yellow-100 max-w-md mx-auto mt-10">
      <p className="font-semibold">Openfort is not configured.</p>
      <p className="mt-2">
        Add <code>NEXT_PUBLIC_OPENFORT_PUBLIC_KEY</code> and{' '}
        <code>NEXT_PUBLIC_SHIELD_API_KEY</code> to your <code>.env.local</code>{' '}
        file.
      </p>
    </div>
  );
}

export function AppProviders({ children }: { children: ReactNode }) {
  if (!publishableKey || !shieldPublishableKey) {
    return (
      <QueryClientProvider client={queryClient}>
        <OpenfortNotConfigured />
      </QueryClientProvider>
    );
  }

  return (
    <QueryClientProvider client={queryClient}>
      <WagmiProvider config={wagmiConfig}>
        <OpenfortWagmiBridge>
          <OpenfortProvider
            publishableKey={publishableKey}
            walletConfig={{
              shieldPublishableKey,
              ethereum: {
                ethereumFeeSponsorshipId:
                  process.env.NEXT_PUBLIC_POLICY_ID || undefined,
              },
              connectOnLogin: false,
              createEncryptedSessionEndpoint: '/api/auth/encryption-session',
            }}
            uiConfig={{
              theme: 'midnight',
              mode: 'dark',
              authProviders: [AuthProvider.GOOGLE, AuthProvider.EMAIL_OTP],
            }}
          >
            <AuthSessionProvider>{children}</AuthSessionProvider>
          </OpenfortProvider>
        </OpenfortWagmiBridge>
      </WagmiProvider>
    </QueryClientProvider>
  );
}

'use client';

import { Bell, Headset } from 'lucide-react';
import { OpenfortButton } from '@openfort/react';
import { usePathname } from 'next/navigation';
import { useMemo } from 'react';
import { useAuthSession } from './auth/auth-session-provider';

const routeTitles: Record<string, string> = {
  '/': 'Dashboard',
  '/home': 'Dashboard',
  '/explore-projects': 'Explore Projects',
  '/create-project': 'Create Project',
  '/tokenization': 'Tokenization',
  '/investment-portal': 'Investment Portal',
  '/digital-assets': 'Digital Assets',
  '/investor-management': 'Investor Management',
  '/investment-requests': 'Investment Requests',
  '/asset-management': 'Asset Management',
  '/swap': 'Swap',
  '/kyc': 'KYC',
  '/account': 'Account',
};

export default function Header() {
  const pathname = usePathname();
  const { backendUser, openfortUser } = useAuthSession();
  const pageTitle = routeTitles[pathname] || 'Page';
  const displayName = useMemo(() => {
    const fullName = [backendUser?.first_name, backendUser?.last_name]
      .filter(Boolean)
      .join(' ')
      .trim();

    return fullName || openfortUser?.name || openfortUser?.email || 'User';
  }, [
    backendUser?.first_name,
    backendUser?.last_name,
    openfortUser?.email,
    openfortUser?.name,
  ]);

  const secondaryLabel =
    openfortUser?.email || backendUser?.role || openfortUser?.id || 'Openfort';
  const avatarLabel = displayName.charAt(0).toUpperCase();

  return (
    <div className="flex h-16 shrink-0 justify-between items-center sticky top-0 z-20 rounded-lg mb-4">
      <div className="flex flex-col gap-2">
        <span className="text-sm font-normal text-white leading-2">
          Hi {displayName}
          <span className="text-[#8087A3] text-base font-normal">
            {' '}
            - {secondaryLabel}
          </span>
        </span>
        <span className="text-[40px] font-bold text-white">{pageTitle}</span>
      </div>

      <div className="flex justify-center items-center gap-4">
        <Headset size={24} className="text-white cursor-pointer" />
        <Bell size={24} className="text-white cursor-pointer" />
        <OpenfortButton label="Wallet" showAvatar />
        <div className="w-12 h-12 rounded-full bg-[#263247] flex justify-center items-center text-white">
          {avatarLabel}
        </div>
      </div>
    </div>
  );
}

