          <CustomButton
            variant="filled"
            className="flex-1 bg-[#7F1D1D] border-[#7F1D1D] text-white hover:bg-[#991B1B] hover:border-[#991B1B]"
            onClick={handleConfirmDelete}
            disabled={isDeleting}
          >
            {isDeleting ? 'Deleting…' : 'Confirm Delete'}
          </CustomButton>
        </div>
      </Modal>
    </div>
  );
}

